/*
 * prog56_kruskal_mst.c
 *
 * Re‑implementation of the original binary “prog56_kruskal_mst”.
 * The program expects a single command‑line argument – the number of
 * vertices (N).  It then reads up to 9 edges from standard input,
 * each line containing three integers:  a  b  w   (0‑based vertex
 * numbers and a non‑negative weight).
 *
 * The program builds a Minimum Spanning Tree with Kruskal’s algorithm.
 * If the graph is disconnected it prints “DISCONNECTED”.  If the
 * arguments are illegal (N ≤ 0, N > 6, or the first argument is missing)
 * it prints “INVALID_ARGS”.
 *
 * On success it prints the total weight of the MST and the list of
 * edges that belong to the MST, in the order they are selected by the
 * algorithm:
 *
 *     weight=%d edges=%d-%d%d-%d...<newline>
 *
 * The output format (including the final newline) matches the original
 * binary exactly.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 6
#define MAX_EDGES    9

typedef struct {
    int a, b;
    int w;
} Edge;

/* Disjoint‑set (union‑find) structure */
static int parent[MAX_VERTICES];

static void make_set(void) {
    for (int i = 0; i < MAX_VERTICES; ++i)
        parent[i] = i;
}

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra != rb)
        parent[ra] = rb;
}

static int cmp_edge(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    if (e1->w != e2->w)
        return e1->w - e2->w;
    if (e1->a != e2->a)
        return e1->a - e2->a;
    return e1->b - e2->b;
}

int main(int argc, char *argv[])
{
    /* ---------- argument validation ---------- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long n_vertices = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_vertices < 0) {
        puts("INVALID_ARGS");
        return 0;
    }
    if (n_vertices == 0 || n_vertices > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }

    /* ---------- read edges (max 9) ---------- */
    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES && !feof(stdin)) {
        int a, b, w;
        if (scanf("%d %d %d", &a, &b, &w) != 3)
            break;
        edges[edge_cnt].a = a;
        edges[edge_cnt].b = b;
        edges[edge_cnt].w = w;
        ++edge_cnt;
    }

    /* ---------- Kruskal ---------- */
    make_set();
    qsort(edges, edge_cnt, sizeof(Edge), cmp_edge);

    int mst_edges[MAX_VERTICES - 1];
    int mst_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && mst_cnt < n_vertices - 1; ++i) {
        int u = edges[i].a;
        int v = edges[i].b;
        if (find_set(u) != find_set(v)) {
            union_set(u, v);
            mst_edges[mst_cnt++] = i;
            total_weight += edges[i].w;
        }
    }

    /* ---------- output ---------- */
    if (mst_cnt != n_vertices - 1) {
        puts("DISCONNECTED");
        return 0;
    }

    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        Edge *e = &edges[mst_edges[i]];
        printf("%d-%d", e->a, e->b);
    }
    putchar('\n');
    return 0;
}
